package pose

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func TestB38R2NestedSchema(t *testing.T) {
	r := newReleaseRepo(t, "v1.0.0")
	good := string(CanonicalJSON(r.manifest))
	for name, raw := range map[string]string{
		"fragment breaking absent": strings.Replace(good, `"breaking": false,`, "", 1),
		"fragment breaking null":   strings.Replace(good, `"breaking": false,`, `"breaking": null,`, 1),
		"fragment SPEC uppercase":  strings.Replace(good, `"spec": "alpha"`, `"SPEC": "alpha"`, 1),
		"fragment refs null":       strings.Replace(good, `"spec": "alpha"`, `"refs":null,"spec":"alpha"`, 1),
	} {
		_, issues := ValidateReleaseManifestBytes([]byte(raw), r.version)
		t.Logf("%s issues=%v", name, issues)
		if len(issues) != 0 {
			t.Error("probe changed")
		}
	}
}
func TestB38R2StatusWorktree(t *testing.T) {
	for _, rel := range []string{".pose/changelogs/v1.0.0.md", ".pose/changelogs/v1.0.0/alpha.md"} {
		r := tagged(t, newReleaseRepo(t, "v1.0.0"))
		os.Remove(filepath.Join(r.root, rel))
		s, e := (Store{Root: r.root}).GetReleaseStatus("")
		if e != nil {
			t.Fatal(e)
		}
		t.Logf("removed %s sound=%v gaps=%v", rel, s.Releases[0].Sound(), s.Releases[0].Gaps)
		if !s.Releases[0].Sound() {
			t.Error("probe changed")
		}
	}
}
func TestB38R2Inventories(t *testing.T) {
	r := newReleaseRepo(t, "v1.0.0")
	relGit(t, r.root, "tag", "v1.0.0")
	os.RemoveAll(filepath.Join(r.root, ".pose/releases"))
	relGit(t, r.root, "tag", "-f", "v1.0.0", relGit(t, r.root, "commit-tree", relGit(t, r.root, "mktree")))
	s, e := (Store{Root: r.root}).GetReleaseStatus("")
	t.Logf("missing snapshot releases=%d error=%v", len(s.Releases), e)
	g := tagged(t, newReleaseRepo(t, "v1.0.0"))
	os.RemoveAll(filepath.Join(g.root, ".pose/releases"))
	control, controlErr := (Store{Root: g.root}).GetReleaseStatus("")
	if controlErr != nil || len(control.Releases) != 1 {
		t.Fatalf("inventory control: %+v %v", control, controlErr)
	}
	t.Logf("list control releases=%d error=%v", len(control.Releases), controlErr)
	real, _ := exec.LookPath("git")
	bin := t.TempDir()
	script := fmt.Sprintf("#!/bin/sh\ncase \"$*\" in *'tag --list'*) echo injected_failure >&2; exit 1;; esac\nexec %q \"$@\"\n", real)
	os.WriteFile(filepath.Join(bin, "git"), []byte(script), 0755)
	t.Setenv("PATH", bin+":"+os.Getenv("PATH"))
	s, e = (Store{Root: g.root}).GetReleaseStatus("")
	t.Logf("list fails releases=%d error=%v", len(s.Releases), e)
}
func TestB38R2ArchiveWitness(t *testing.T) {
	r := tagged(t, newReleaseRepo(t, "v1.0.0"))
	fs := append([]ReleaseFragment{}, r.manifest.Fragments...)
	fs[0].Spec = "beta"
	r.manifest = NewReleaseManifest(r.version, "", r.manifest.PreparedAt, fs, ReleasePolicy{SchemaVersion: 1}, ChangelogPolicy{}, r.manifest.VersionEvidence)
	relWrite(t, r.root, ".pose/releases/v1.0.0/manifest.json", string(CanonicalJSON(r.manifest)))
	a := LoadArchivedFragments(r.root)
	t.Logf("archive=%+v", a)
	l := newArchivalLedger(a, func(string) bool { return true })
	_, note, ok := l.resolve("beta", ".pose/changelogs/unreleased/alpha.md", "")
	t.Logf("ledger wrong spec accepted=%v note=%q", ok, note)
	if len(a) != 1 || !a[0].Intact || a[0].Spec != "beta" {
		t.Error("probe changed")
	}
}
func TestB38R2Notes(t *testing.T) {
	r := newReleaseRepo(t, "v1.0.0")
	r.notes = "# An unrelated release\n"
	r.manifest.NotesDigest = ReleaseDigest(r.notes)
	r.writeAll(t)
	s := snapshotOf(t, tagged(t, r))
	t.Logf("unrelated notes intact=%v gaps=%v", s.Intact(), s.Gaps)
}
func TestB38R2VersionPolicy(t *testing.T) {
	for _, mode := range []string{"json", "nil-policy-source"} {
		r := newReleaseRepo(t, "v1.0.0")
		p := ReleasePolicy{SchemaVersion: 1}
		e := map[string]string{"source": "VERSION", "value": r.version}
		if mode == "json" {
			p.VersionSource = &ReleaseVersionSource{Path: "package.json", Kind: "json", Key: "version"}
			e["source"] = "package.json"
			e["kind"] = "json"
			relWrite(t, r.root, "package.json", `{"version":"9.9.9"}`)
		}
		r.manifest = NewReleaseManifest(r.version, "", r.manifest.PreparedAt, r.manifest.Fragments, p, ChangelogPolicy{}, e)
		r.writeAll(t)
		relWrite(t, r.root, ".pose/policy/release.json", string(CanonicalJSON(p)))
		if mode == "nil-policy-source" {
			relWrite(t, r.root, "VERSION", "9.9.9\n")
		}
		s := snapshotOf(t, tagged(t, r))
		t.Logf("%s intact=%v gaps=%v limits=%v", mode, s.Intact(), s.Gaps, s.Limits)
	}
}
func TestB38R2PolicyValidation(t *testing.T) {
	r := newReleaseRepo(t, "v1.0.0")
	p := ReleasePolicy{SchemaVersion: 1, AdoptedAt: "2026-01-01"}
	r.manifest = NewReleaseManifest(r.version, "", r.manifest.PreparedAt, r.manifest.Fragments, p, ChangelogPolicy{}, r.manifest.VersionEvidence)
	r.writeAll(t)
	relWrite(t, r.root, ".pose/policy/release.json", string(CanonicalJSON(p)))
	_, err := LoadReleasePolicy(r.root)
	s := snapshotOf(t, tagged(t, r))
	t.Logf("ordinary policy error=%v historical intact=%v gaps=%v", err, s.Intact(), s.Gaps)
}
func TestB38R2NestedEmptyShapes(t *testing.T) {
	r := newReleaseRepo(t, "v1.0.0")
	m := NewReleaseManifest(r.version, "", r.manifest.PreparedAt, nil, ReleasePolicy{SchemaVersion: 1}, ChangelogPolicy{}, r.manifest.VersionEvidence)
	raw := CanonicalJSON(m)
	var x map[string]any
	json.Unmarshal(raw, &x)
	t.Logf("control=%v", x["fragments"])
}
func TestB38R2InvalidCategory(t *testing.T) {
	r := newReleaseRepo(t, "v1.0.0")
	r.body = strings.Replace(r.body, "category: fixed", "category: invented", 1)
	f := r.manifest.Fragments[0]
	f.Category = "invented"
	f.Digest = ReleaseDigest(r.body)
	r.manifest = NewReleaseManifest(r.version, "", r.manifest.PreparedAt, []ReleaseFragment{f}, ReleasePolicy{SchemaVersion: 1}, ChangelogPolicy{}, r.manifest.VersionEvidence)
	r.notes = RenderReleaseNotes(r.version, []ReleaseFragment{f}, ChangelogPolicy{})
	r.writeAll(t)
	_, err := LoadReleaseFragments(filepath.Join(r.root, ".pose/changelogs", r.version), ChangelogPolicy{})
	s := snapshotOf(t, tagged(t, r))
	t.Logf("ordinary fragment error=%v historical intact=%v gaps=%v", err, s.Intact(), s.Gaps)
}

